using System.Text.RegularExpressions;

namespace Companion.Api.Services;

/// <summary>
/// Finds the licence documents that ship with every PlatinVault artifact: <c>LICENSE</c> (the official plain text of the GNU AGPL v3 -
/// PlatinVault is licensed under AGPL-3.0-only) and <c>THIRD-PARTY-NOTICES.md</c> (copyright notices and licence texts of the bundled open-source components, generated by
/// scripts/build-notices.ps1). In Development they are read straight from the repository root, so a regenerated file is served at
/// once; the Docker image keeps them in the application folder (/app/docs/). They are delivered three ways: the endpoint
/// GET /api/docs/licenses, the bridge download ZIP and the image itself.
/// </summary>
public sealed partial class LicenseFiles
{
    public const string LicenseFileName = "LICENSE";
    public const string NoticesFileName = "THIRD-PARTY-NOTICES.md";

    /// <summary>
    /// One licence document: the query key of the endpoint ("license" / "notices"), its file name and where it was found. The licence is
    /// the official plain text of the GNU AGPL v3; the notices are Markdown.
    /// </summary>
    public sealed record Document(string Key, string FileName, string Path)
    {
        public bool IsMarkdown => FileName.EndsWith(".md", StringComparison.OrdinalIgnoreCase);
    }

    private static readonly (string Key, string FileName)[] Known =
    [
        ("license", LicenseFileName),
        ("notices", NoticesFileName),
    ];

    private readonly string[] _roots;

    public LicenseFiles(IWebHostEnvironment environment)
    {
        // Development: the repository root is two levels above src/Companion.Api (same convention as HandbookFiles and BridgeBundle)
        var repository = Path.GetFullPath(Path.Combine(environment.ContentRootPath, "..", ".."));
        var docs = Path.Combine(AppContext.BaseDirectory, "docs");
        _roots = environment.IsDevelopment() ? [repository, docs] : [docs];
    }

    /// <summary>True for the keys the endpoint accepts ("license", "notices"; empty means "license").</summary>
    public static bool IsKnownKey(string? key) => Normalize(key) is not null;

    private static string? Normalize(string? key)
    {
        var value = key?.Trim();
        if (string.IsNullOrEmpty(value))
        {
            return "license";
        }
        foreach (var (known, _) in Known)
        {
            if (value.Equals(known, StringComparison.OrdinalIgnoreCase))
            {
                return known;
            }
        }
        return null;
    }

    /// <summary>The document for this key, or null when the key is unknown or the file is not there.</summary>
    public Document? Find(string? key)
    {
        var normalized = Normalize(key);
        if (normalized is null)
        {
            return null;
        }

        var fileName = Known.First(k => k.Key == normalized).FileName;
        foreach (var root in _roots)
        {
            var path = Path.Combine(root, fileName);
            if (File.Exists(path))
            {
                return new Document(normalized, fileName, path);
            }
        }
        return null;
    }

    /// <summary>Every licence document that is available (the licence first).</summary>
    public IEnumerable<Document> FindAll() => Known.Select(k => Find(k.Key)).OfType<Document>();

    /// <summary>
    /// The text as it is shipped: HTML comments are notes to the owner and are never delivered, neither by the endpoint nor in the
    /// bridge ZIP (the AGPL text has none, so it passes unchanged apart from line endings and surrounding blank lines).
    /// </summary>
    public static string ReadShippedText(string path) => ToShippedText(File.ReadAllText(path));

    public static string ToShippedText(string markdown)
    {
        var text = HtmlComment().Replace(markdown, string.Empty).Replace("\r\n", "\n").TrimStart('﻿');
        // Only blank lines are dropped at the start: the AGPL text centres its title with leading spaces, which must stay
        var trimmed = text[LeadingBlankLines().Match(text).Length..].TrimEnd();
        return trimmed.Length > 0 ? trimmed + "\n" : string.Empty;
    }

    [GeneratedRegex("<!--.*?-->", RegexOptions.Singleline)]
    private static partial Regex HtmlComment();

    [GeneratedRegex(@"^(?:[ \t]*\n)*")]
    private static partial Regex LeadingBlankLines();
}
